          function sleep_sound(ms) {
            if (!gameCR.exit && ms != 0) {
              if (ms < 52) {
                return new Promise((resolve) => setTimeout(resolve, ms))
              } else {
                return new Promise((resolve) => {
                  ;(async () => {
                    const result = blocklyToPhaser(true, 'phaserWait',ms)
                    ___abort_sounds.push(result._cancel)
                    if (result instanceof Promise) {
                      await result
                      for (let index = ___abort_sounds.length - 1; index > -1; index--) {
                        if (___abort_sounds[index] == result._cancel) {
                          ___abort_sounds.splice(index, 1)
                          break
                        }
                      }
                      resolve()
                    }
                  })()
                })
              }
            }
          }
          function sleepjs(ms) {
            if(!gameCR.exit&&ms!=0){
              if (ms < 52) {
                return new Promise((resolve) => setTimeout(resolve, ms))
              } else {
                let abortHandler
                return new Promise((resolve) => {
                  const timeoutId = setTimeout(() => {
                    for (let index = ___abort_sleeps.length - 1; index > -1; index--) {
                      if (___abort_sleeps[index] == abortHandler) {
                        ___abort_sleeps.splice(index, 1)
                        break
                      }
                    }
                    resolve()
                  }, ms)
                  // Abort handling with event listener
                  abortHandler = () => {
                    clearTimeout(timeoutId)
                    resolve()
                  }
                  ___abort_sleeps.push(abortHandler)
                })
              }
            }
          }
